    {
      "keystrokes": "cat > /tmp/qm.py <<'PYEOF'
import socket, time, sys
sock='/tmp/qemu-monitor.sock'
def send(cmd, wait=0.3, quiet=False):
    s=socket.socket(socket.AF_UNIX, socket.SOCK_STREAM); s.settimeout(5); s.connect(sock)
    time.sleep(0.2)
    try: s.recv(4096)
    except: pass
    if not quiet: s.sendall((cmd+'\n').encode())
    time.sleep(wait)
    out=b''
    try:
        while True:
            d=s.recv(4096)
            if not d: break
            out+=d
    except socket.timeout:
        pass
    s.close()
    t=out.decode('utf-8','replace').replace('\x1b[K','').replace('\x1b[D','')
    return t
if __name__=='__main__':
    print(send(sys.argv[1] if len(sys.argv)>1 else 'info status', wait=float(sys.argv[2]) if len(sys.argv)>2 else 0.4))
PYEOF
echo 'helper created'; ls -la /tmp/qm.py
",
      "duration": 1.0
    },
    {
      "keystrokes": "python3 /tmp/qm.py 'info status' 0.4 2>&1 | grep -a 'VM status\|OK'
",
  "duration": 2.0
}

