import socket, subprocess, time, sys
def mon(cmd, wait_prompt=True):
    s=socket.socket(socket.AF_UNIX,socket.SOCK_STREAM); s.settimeout(8)
    s.connect('/tmp/qemu-monitor.sock'); time.sleep(0.3)
    try: s.recv(65536)
    except: pass
    s.sendall(cmd.encode()+b'\n')
    buf=b''; t=time.time()
    while time.time()-t<10:
        try:
            d=s.recv(65536)
            if not d: break
            buf+=d
            if wait_prompt and b'(qemu)' in buf: break
        except: break
    s.close(); return buf
mon('screendump /tmp/c.pgm')
time.sleep(0.2)
if __name__=='__main__':
    try:
        subprocess.run(['convert','/tmp/c.pgm','/tmp/c.png'],timeout=10,check=False)
        print('PNG saved')
    except Exception as e:
        print('convert err',e)
    # OCR
    for f in ['/tmp/c.png','/tmp/c.pgm']:
        try:
            out=subprocess.run(['tesseract',f,'stdout','--psm','6'],capture_output=True,text=True,timeout=30)
